let campaign, edition={version:'3.0.0',title:'第五日之城 · 合作冒险',defaultRoomMode:'party',decisionPolicy:'first-valid-revision'}, maps=[], state, session=null, stream, selected, mode='move', activeRoute=null, activeNode=null, busy=false, seats=[], agents=[], grid=true, view='table', toastTimer;
let draft=null, draftHistory=[], brush='.', painted=0, painting=false;
const queryRoom=new URLSearchParams(location.search).get('room');
const queryJoin=new URLSearchParams(location.search).get('join')==='1';
function actorForUi(){return{role:state?.viewer?.role??session?.role,characterId:state?.viewer?.characterId??session?.characterId??null,roomMode:state?.roomMode??state?.viewer?.roomMode??session?.roomMode??'hosted',canManage:state?.viewer?.canManage??session?.canManage??false};}
function capabilities(){if(!session)return{allowedActions:[],canManage:false,controlAll:false,canProgress:false};if(Array.isArray(state?.capabilities?.allowedActions))return state.capabilities;if(Array.isArray(state?.viewer?.allowedActions))return state.viewer;const actor=actorForUi();if(rules.capabilitiesForActor)return rules.capabilitiesForActor(actor);const legacyHost=actor.role==='host';return{allowedActions:legacyHost?['move','attack','guard','heal','skill','endTurn','choose','travel','rest','retreat','finale','saveMap','loadMap','startEncounter']:['move','attack','guard','heal','skill','endTurn'],canManage:legacyHost,controlAll:legacyHost,canProgress:legacyHost};}
const canManage=()=>capabilities().canManage===true;
const canProgress=()=>capabilities().canProgress===true;
