function availableCells(map,unit){
 if(!unit||!canAct(unit)||mode!=='move')return new Set();const occupied=new Set([...state.party,...(state.combat?.enemies??[]).filter(p=>p.hp>0)].filter(p=>p.id!==unit.id).map(p=>p.x+','+p.y));const budget=state.phase==='combat'?unit.move:5;const queue=[{x:unit.x,y:unit.y,c:0}],best=new Map([[unit.x+','+unit.y,0]]);
 for(let i=0;i<queue.length;i++){const p=queue[i];for(const [dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){const x=p.x+dx,y=p.y+dy,key=x+','+y,t=map.tiles[y]?.[x];if(!t||['#','~'].includes(t)||occupied.has(key))continue;const c=p.c+(t==='^'?2:1);if(c<=budget&&c<(best.get(key)??Infinity)){best.set(key,c);queue.push({x,y,c});}}}best.delete(unit.x+','+unit.y);return new Set(best.keys());
}
function mapSVG(map,{editing=false}={}){
 const s=36, ox=25, oy=24, w=map.width*s, h=map.height*s, prefix=editing?'e':'g', materialNames=['ground','wall','water','bridge','high','curse'];
 const defs=`<defs>${materialNames.map((name,i)=>`<pattern id="${prefix}${name}" width="${name==='water'?144:name==='ground'?72:36}" height="${name==='water'?144:name==='ground'?72:36}" patternUnits="userSpaceOnUse" viewBox="0 0 100 100"><image href="/assets/terrain.png" x="${-100*(i%3)}" y="${-100*Math.floor(i/3)}" width="300" height="200" preserveAspectRatio="none"/></pattern>`).join('')}<clipPath id="partyPortraitClip"><circle r="12"/></clipPath><filter id="tokenShadow"><feDropShadow dx="0" dy="2" stdDeviation="2" flood-opacity=".75"/></filter></defs>`;
 const variantCells=new Map();if(!editing)for(const v of activeMapVariants(map))for(const c of v.changes)variantCells.set(c.x+','+c.y,v.id);let tiles='',overlays='',labels='',tokens='';const seen=new Set(state?.explored?.[map.id]??[]),reach=editing?new Set():availableCells(map,currentUnit());
 map.tiles.forEach((row,y)=>[...row].forEach((t,x)=>{const X=ox+x*s,Y=oy+y*s,seed=(x*7+y*13)%11;let shape='';
  const material=terrain[t]?.class??'ground';
  shape=`<rect x="${X}" y="${Y}" width="36" height="36" fill="url(#${prefix}${material})"/>`;
  if(t==='#')shape+=`<path d="M${X} ${Y+34}h36" stroke="#07160c" stroke-width="3" opacity=".75"/>`;
  if(t==='.'&&map.id==='canal'&&seed<4)shape+=`<path d="M${X+12} ${Y+29}v-20m0 4q-8-7-10-2m10 6q10-10 14-4m-14 6q-7-7-10-2" stroke="#6f8d39" stroke-width="2.5" fill="none"/><path d="M${X+12} ${Y+13}v-6" stroke="#c8b764" stroke-width="2"/>`;
  if(t==='.'&&map.id==='underworld')shape+=`<rect x="${X}" y="${Y}" width="36" height="36" fill="#161626" opacity=".28"/>`;
  tiles+=shape;if(!editing&&!seen.has(x+','+y))overlays+=`<rect x="${X}" y="${Y}" width="36" height="36" fill="#09180f" opacity=".25"/>`;if(reach.has(x+','+y))overlays+=`<rect class="reachable" x="${X+1}" y="${Y+1}" width="34" height="34"/>`;overlays+=`<rect class="tile-hit" data-x="${x}" data-y="${y}" x="${X}" y="${Y}" width="36" height="36"><title>${String.fromCharCode(65+x)}${y+1} · ${esc(editing?terrain[t]?.name:terrainNameFor(map,x,y))}${map.pois?.some(p=>p.x===x&&p.y===y)?' · '+esc(map.pois.find(p=>p.x===x&&p.y===y).name)+'：'+esc(map.pois.find(p=>p.x===x&&p.y===y).description):''}</title></rect>`;
 }));
 for(let x=0;x<map.width;x++)labels+=`<text x="${ox+x*s+18}" y="15" text-anchor="middle" fill="#a7987b" font-family="Georgia" font-size="10">${String.fromCharCode(65+x)}</text>`;
 for(let y=0;y<map.height;y++)labels+=`<text x="12" y="${oy+y*s+22}" text-anchor="middle" fill="#a7987b" font-family="Georgia" font-size="10">${y+1}</text>`;
 let lines='';for(let x=0;x<=map.width;x++)lines+=`M${ox+x*s} ${oy}v${h}`;for(let y=0;y<=map.height;y++)lines+=`M${ox} ${oy+y*s}h${w}`;
 for(const poi of map.pois??[])labels+=`<circle cx="${ox+poi.x*s+18}" cy="${oy+poi.y*s+12}" r="4" fill="#c6ae6b" stroke="#15281c" stroke-width="1.5"/><text class="poi-label" text-anchor="middle" x="${ox+poi.x*s+18}" y="${oy+poi.y*s+31}">${esc(poi.name)}</text>`;
 if(editing){tokens=`<g pointer-events="none"><circle cx="${ox+map.spawn.x*s+18}" cy="${oy+map.spawn.y*s+18}" r="13" fill="#173c52" stroke="#ead196" stroke-width="2"/><text x="${ox+map.spawn.x*s+18}" y="${oy+map.spawn.y*s+24}" text-anchor="middle" fill="#f1cc72" font-size="20">☼</text></g>`;}
 else {const units=[...state.party.map((p,i)=>({...p,index:i})),...(state.combat?.enemies??[]).map(p=>({...p,enemy:true}))];for(const p of units){if(p.hp<=0&&p.enemy)continue;const X=ox+p.x*s+18,Y=oy+p.y*s+18,isSelected=p.id===selected;tokens+=`<g class="map-token" data-unit="${esc(p.id)}" data-enemy="${p.enemy?'true':'false'}" transform="translate(${X},${Y})" role="button" tabindex="0" aria-label="${esc(p.name)} ${p.hp}/${p.maxHp}生命"><title>${esc(p.name)} · ${p.hp}/${p.maxHp} HP · ${String.fromCharCode(65+p.x)}${p.y+1}</title>${isSelected?'<circle r="18" fill="none" stroke="#b5d995" stroke-width="1" opacity=".8"/>':''}<circle class="token-ring" r="14.5" fill="${p.enemy?'#6d302b':portraitColors[p.index%4]}" stroke="${p.enemy?'#e28869':isSelected?'#e3d19a':'#cbb285'}" stroke-width="2" filter="url(#tokenShadow)"/>${p.enemy?'<path d="M-10 9Q-9 0 0 0Q9 0 10 9" fill="#311e17"/><ellipse cy="-4" rx="6" ry="7" fill="#9c7850"/><path d="M-7-5Q-6-14 1-13Q8-12 7-4L4-7L-5-7Z" fill="#171f18"/>':`<g clip-path="url(#partyPortraitClip)"><svg x="-12" y="-12" width="24" height="24" viewBox="0 0 100 100"><image href="/assets/companions.png" x="${-100*p.index}" y="-8" width="400" height="200" preserveAspectRatio="none"/></svg></g>`}<rect x="-12" y="15" width="24" height="3" fill="#311b21"/><rect x="-12" y="15" width="${Math.max(0,24*p.hp/p.maxHp)}" height="3" fill="${p.enemy?'#d47765':'#7db49c'}"/>${p.down?'<path d="M-7-7L7 7M7-7L-7 7" stroke="#e2a086" stroke-width="3"/>':''}${p.guarding?'<text x="10" y="-8" font-size="12" fill="#f5d491">♜</text>':''}</g>`;}}
 return `<svg viewBox="0 0 ${w+34} ${h+33}" xmlns="http://www.w3.org/2000/svg" aria-label="${esc(map.name)}，16列12行"><rect width="100%" height="100%" fill="#0b1c12"/>${defs}${tiles}<path class="map-grid" d="${lines}" fill="none" stroke="#302a20" stroke-opacity=".45" stroke-width=".6"/>${overlays}${labels}${tokens}</svg>`;
}
function renderMap(){const map=currentMap();if(!map)return;$('map-name').textContent=map.name;$('region-label').textContent=state.phase==='combat'?`第 ${state.combat.round} 回合 · ${state.party.find(p=>p.id===state.combat.turn)?.name??'敌方'}的回合`:map.id==='underworld'?'亡途 · 骨渡':'第五日 · 湖上城';$('game-board').innerHTML=mapSVG(map);$('game-board').classList.toggle('no-grid',!grid);const prior=$('travel-map').value;$('travel-map').innerHTML=maps.map(m=>`<option value="${m.id}">${esc(m.name)}${m.id==='underworld'?' · 亡途':''}</option>`).join('');$('travel-map').value=maps.some(m=>m.id===prior)?prior:map.id;const encounter=$('encounter-controls');encounter.hidden=!state.customMaps?.[state.mapId];$('encounter-start').disabled=busy||!may('startEncounter')||state.phase!=='exploration';$('encounter-template').disabled=!may('startEncounter');const changes=activeMapVariants(map);$('world-changes').hidden=!changes.length;$('world-changes').innerHTML=changes.map(v=>'<strong>街区改变</strong> '+esc(v.description)).join('<br>');}
function renderControls(){if(!state)return;const u=currentUnit(),act=canAct(u),combat=state.phase==='combat';document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.disabled=busy||!act||!may(b.dataset.mode)||(b.dataset.mode==='attack'&&!combat);});$('guard').disabled=busy||!act||!may('guard')||!combat||u.ap<1||u.guarding;$('end-turn').disabled=busy||!act||!may('endTurn')||!combat;$('rest').disabled=busy||!may('rest')||!['exploration','defeat'].includes(state.phase);$('retreat').disabled=busy||!may('retreat')||!combat;$('retreat').hidden=!combat;$('travel-go').disabled=busy||!may('travel')||state.phase!=='exploration';$('travel-map').disabled=$('travel-go').disabled;$('save-now').disabled=busy||!canManage();$('export-game').disabled=!canManage();$('agent-controls').hidden=false;$('agent-dm').disabled=!canManage();$('agent-character').disabled=!canManage();$('editor-save').disabled=busy||!may('saveMap')||state.phase!=='exploration';$('editor-play').disabled=busy||!may('loadMap')||state.phase!=='exploration';
 $('unit-status').textContent=u?u.name+' · '+(combat?'AP '+u.ap+' · 移动 '+u.move+' · 射程 '+u.range:'每次 5 步')+(!controlled(u.id)?' · 他人席位':''):'';let skillButton=$('skill-button');if(!skillButton){skillButton=document.createElement('button');skillButton.id='skill-button';$('end-turn').before(skillButton);skillButton.addEventListener('click',()=>{if(currentUnit()?.id==='nelli')action({type:'skill',characterId:selected});else setMode('skill');});}skillButton.innerHTML=`<b>✦</b>${esc(skillNames[u?.id]??'特技')} <small>${u?.skillCost??1}AP${u?.skillEmpowered?' ↑':''}</small>`;skillButton.hidden=!skillNames[u?.id];skillButton.disabled=busy||!act||!may('skill')||!combat||u.skillUsed||u.ap<(u.skillCost??1);skillButton.classList.toggle('active',mode==='skill');if(u?.skillUsed)skillButton.title='本场战斗已使用';else skillButton.title=u?.skillEmpowered?'关系达到 3：特技增强':'每战一次；关系≤-3 时耗 2 AP';
 document.querySelectorAll('[data-choice]').forEach(b=>{b.disabled=b.dataset.allowed!=='true'||busy||!may('choose')||state.phase!=='exploration';});document.querySelectorAll('[data-travel]').forEach(b=>b.disabled=busy||!may('travel')||state.phase!=='exploration');$('finale')?.toggleAttribute('disabled',busy||!may('finale')||state.phase!=='exploration');$('story-rest')?.toggleAttribute('disabled',busy||!may('rest'));$('editor-export').disabled=!canManage();$('editor-name').disabled=!canManage();$('editor-description').disabled=!canManage();$('editor-reset').disabled=!canManage();$('editor-undo').disabled=!canManage()||!draftHistory.length;document.querySelectorAll('[data-brush]').forEach(b=>b.disabled=!canManage());}
function eligibleNodes(){const chapters=chapterProgress();return(campaign.nodes??[]).filter(n=>(!n.chapter||!chapters.chapters.length||n.chapter===chapters.currentChapter)&&!state.flags.includes('node:'+n.id)&&!state.completedRoutes.includes(n.route)&&!state.failedRoutes.includes(n.route)&&meetsRequirements(state,n.requires));}
function choiceDetails(c){if(c.preview)return c.preview;const parts=[];if(c.cost)parts.push('消耗 '+Object.entries(c.cost).map(([k,v])=>`${v} ${resourceNames[k]??k}`).join(' · '));const e=c.effects??{};if(e.resources)parts.push(Object.entries(e.resources).map(([k,v])=>`${resourceNames[k]??k} ${v>0?'+':''}${v}`).join(' · '));if(e.completeRoute)parts.push('完成此主线');if(c.encounter)parts.push('⚔ '+c.encounter.name);return parts.join(' ｜ ');}
function renderStory(){
 const all=eligibleNodes(),local=all.filter(n=>n.map===state.mapId),chapters=chapterProgress(),chapter=chapters.current??(chapters.allSettled?chapters.chapters.at(-1):chapters.chapters.find(c=>c.unlocked)??chapters.chapters[0]),routes=(campaign.routes??[]).filter(r=>!chapter||campaign.nodes.some(n=>n.chapter===chapter.id&&n.route===r.id));if(!routes.some(r=>r.id===activeRoute)){activeRoute=local[0]?.route??routes[0]?.id;activeNode=null;}
 $('routes').innerHTML=routes.map(r=>{const ns=campaign.nodes.filter(n=>n.route===r.id&&(!n.chapter||!chapter||n.chapter===chapter.id)),done=ns.filter(n=>state.flags.includes('node:'+n.id)).length,complete=state.completedRoutes.includes(r.id),failed=state.failedRoutes.includes(r.id);return `<button class="route ${r.id===activeRoute?'active':''}" data-route="${esc(r.id)}" title="${esc(r.title)}"><b>${esc(r.title.split(/[：:]/)[0])}</b><small class="route-subtitle">${esc(r.title.split(/[：:]/).slice(1).join('：'))}</small><span class="route-progress">${ns.map((n,i)=>`<i class="${i<done?'done':''}"></i>`).join('')}</span><span>${complete?'已完成':failed?'已失去':`${done} / ${ns.length}`}</span></button>`;}).join('');
 let html='';if(state.ending){html=`<div class="ending-seal">☼</div><div class="story-meta"><span>第五日的归宿</span><span>旅程已封存</span></div><h2>${esc(state.ending.title)}</h2><p class="story-text">${esc(Array.isArray(state.ending.text)?state.ending.text.join('\n\n'):state.ending.text)}</p><div class="story-consequence">${esc(state.ending.consequences??'')}</div>${(state.ending.followups??[]).filter(f=>!(state.ending.consequences??'').includes(typeof f==='string'?f:f.text??'')).map(f=>`<div class="ending-followup">${typeof f==='string'?esc(f):`<h3>${esc(f.title??'后日谈')}</h3><p>${esc(f.text??'')}</p>`}</div>`).join('')}`;}
 else if(state.phase==='combat'){const turn=state.party.find(p=>p.id===state.combat.turn);html=`<div class="combat-banner">⚔ ${esc(state.combat.name)}<br>第 ${state.combat.round} 回合 · ${esc(turn?.name??'敌方')}正在行动${state.combat.training?'<br>工坊遭遇 · 不产生剧情奖励':''}</div><h2>在此刻站稳</h2><p class="story-text">选择你的战术。移动不消耗行动力；攻击、防御与救治消耗行动力。每位同行者还拥有一种每战限用一次的特技。</p>${state.combat.enemies.map(e=>`<div class="story-consequence">${esc(e.name)}<br>生命 ${e.hp}/${e.maxHp} · 攻 ${e.attack} · 护甲 ${e.armor} · 射程 ${e.range}</div>`).join('')}<p class="editor-note">点击敌棋可攻击；选择救治后点击相邻同伴。撤退将增加蚀影。</p>`;}
 else if(state.phase==='defeat')html='<h2>蚀影中的余烬</h2><p class="story-text">你们被迫退回营地，城中的承诺仍在等候。</p><button class="story-choice" id="story-rest"><strong>☾ 扎营，重新出发</strong><small>恢复全队生命；缺粮会增加蚀影。</small></button>';
 else {
 const route=routes.find(r=>r.id===activeRoute),rs=local.filter(n=>n.route===activeRoute);if(!rs.some(n=>n.id===activeNode))activeNode=rs[0]?.id;const rawNode=rs.find(n=>n.id===activeNode),node=rawNode&&rules.sceneForState?rules.sceneForState(state,rawNode):rawNode;
 if(rs.length>1)html+=`<div class="node-switch">${rs.map(n=>`<button data-node="${esc(n.id)}" class="${n.id===activeNode?'active':''}">${esc(n.title)}</button>`).join('')}</div>`;
 if(node){const legal=legalChoices(state,campaign).find(n=>n.id===node.id),ids=new Set(legal?.choices.map(c=>c.id)??[]);html+=`<div class="story-meta"><span>${esc(route?.title??'城邦见闻')}</span><span>${esc(currentMap().name)}</span></div><h2>${esc(node.title)}</h2><p class="story-text">${esc(Array.isArray(node.text)?node.text.join('\n\n'):node.text)}</p>${node.choices.map(c=>`<button class="story-choice" data-choice="${esc(c.id)}" data-choice-node="${esc(node.id)}" data-allowed="${ids.has(c.id)}" ${!ids.has(c.id)?'disabled':''}><strong>${esc(c.label)}</strong><small>${esc(choiceDetails(c))}${!ids.has(c.id)?' ｜ 条件或资源不足':''}</small></button>`).join('')}`;}
 else{const next=all.find(n=>n.route===activeRoute),complete=state.completedRoutes.includes(activeRoute),failed=state.failedRoutes.includes(activeRoute);html+=`<div class="story-meta"><span>${esc(route?.title??'')}</span><span>${complete?'已完成':failed?'已失去':'行旅线索'}</span></div><h2>${complete?'承诺已有回响':failed?'这条路已经改变':esc(next?.title??'未竟的承诺')}</h2><p class="story-text">${esc(complete?'这条主线已完成，其他故事仍在等候。':failed?'你的抉择使这条道路关闭。城中仍有别的道路。':route?.summary??currentMap().description)}</p>`;if(next&&next.map!==state.mapId)html+=travelClue(next);else if(!next&&!complete&&!failed)html+='<p class="story-empty">此处尚无线索。探索其他主线，或检查已做出的选择。</p>';}
 const elsewhere=all.filter(n=>n.map!==state.mapId&&n.route!==activeRoute);if(!node&&elsewhere.length)html+=elsewhere.slice(0,2).map(travelClue).join('');if(chapters.chapters.length?chapters.allSettled:(campaign.routes??[]).every(r=>state.completedRoutes.includes(r.id)||state.failedRoutes.includes(r.id)))html+='<button id="finale" class="story-choice"><strong>☼ 见证第五日的终局</strong><small>所有章节都已有归宿，你可在此刻封存结局。</small></button>';
 }
 const npcReferences=(campaign.majorNpcs??[]).filter(n=>!n.knownFromFlag||state.flags.includes(n.knownFromFlag)).filter(n=>html.includes(esc(n.name)));if(npcReferences.length)html+=npcReferences.map(n=>`<button class="npc-profile-link" data-npc-profile="${esc(n.id)}">查看${esc(n.name)}档案 ↗</button>`).join('');$('story').innerHTML=html;renderControls();
}
function travelClue(node){return `<button class="travel-clue" data-travel="${esc(node.map)}" data-travel-route="${esc(node.route)}"><strong>→ ${node.map==='underworld'?'进入亡途':'前往'+esc(mapById(node.map)?.name??node.map)}</strong><small>${esc(node.title)} · ${esc(campaign.routes.find(r=>r.id===node.route)?.title??'')}</small></button>`;}
function renderChapters(){const progress=chapterProgress(),current=progress.current??progress.chapters.at(-1),panel=$('chapter-summary');if(!progress.chapters.length){panel.hidden=true;return;}panel.hidden=false;const index=progress.chapters.findIndex(c=>c.id===current?.id)+1;panel.innerHTML=`<div class="chapter-caption"><span>第 ${index} 章 / ${progress.chapters.length} 章</span><button id="chapter-recap">旅程回顾 ↗</button></div><h3>${esc(current?.title??'旅程已封存')}</h3><p>${esc(current?.summary??'')}</p><div class="chapter-tracks">${progress.chapters.map((c,i)=>`<span class="${c.settled?'settled':c.id===progress.currentChapter?'current':''}" title="${esc(c.title)} · ${c.progress}/${c.total}">${c.settled?'✓':i+1}</span>`).join('')}<small>${progress.allSettled?'三章已结算':`本章结算 ${current?.progress??0} / ${current?.total??0}`}</small></div>`;
 $('journey-body').innerHTML=progress.chapters.map((c,i)=>{const ns=campaign.nodes.filter(n=>n.chapter===c.id),completed=ns.filter(n=>state.flags.includes('node:'+n.id));return `<section class="chapter-recap ${c.settled?'settled':c.unlocked?'unlocked':'locked'}"><div class="chapter-recap-meta"><span>第 ${i+1} 章</span><b>${c.settled?'已结算':c.unlocked?'正在发生':'尚未开启'}</b></div><h3>${esc(c.title)}</h3><p>${esc(c.summary)}</p><div class="recap-route-progress">${campaign.routes.filter(r=>ns.some(n=>n.route===r.id)).map(r=>{const nodes=ns.filter(n=>n.route===r.id),done=nodes.filter(n=>state.flags.includes('node:'+n.id)).length;return `<span>${esc(r.title)} <b>${done}/${nodes.length}</b></span>`;}).join('')}</div>${completed.length?completed.map(n=>{const line=state.journal.find(j=>(j.text??'').startsWith(n.title));const chosen=line?n.choices.find(choice=>line.text.includes(choice.label)):null;return `<div class="recap-event"><strong>✓ ${esc(n.title)}</strong><p>${esc(line?.text??'这道选择已被画卷记下。')}</p>${chosen?.effects?.text?`<p class="recap-consequence">${esc(chosen.effects.text)}</p>`:''}</div>`;}).join(''):`<p class="muted">${c.unlocked?'等待你写下第一个决定。':'前章完成后开启。'}</p>`}</section>`;}).join('')+`<section class="journey-current"><h3>此刻的城邦</h3><div>${Object.entries(resourceNames).map(([k,v])=>`<span>${v} <b>${state.resources[k]}</b></span>`).join('')}</div><p>完成 ${state.completedRoutes.length} 条章内路线 · 失去 ${state.failedRoutes.length} 条章内路线</p></section>`;
}
function renderJournal(){const el=$('journal'),atBottom=el.scrollHeight-el.scrollTop-el.clientHeight<25;el.innerHTML=state.journal.slice(-80).map(j=>`<div class="journal-entry"><span>${String(j.clock??0).padStart(3,'0')}</span><div>${esc(j.text)}</div></div>`).join('')||'<span class="muted">旅程开始。</span>';if(atBottom)el.scrollTop=el.scrollHeight;}
async function refreshSeats(){if(!session)return;try{const data=await request(roomUrl('seats'));seats=data.seats??[];agents=data.agents??[];renderSeats();}catch(e){toast(e.message,true);}}
function seatsMarkup(){if(!session)return '<p class="muted">开启旅程后可邀请同行者</p>';return seats.map(s=>`<div class="seat-row"><i class="seat-dot"></i><span>${esc(s.name)}${s.id===session.seatId?' · 你':''}</span><small>${s.role==='host'?'主持人':esc(state.party.find(p=>p.id===s.characterId)?.name??'队员')}${s.canManage&&s.role!=='host'?' · 管理员':''}</small></div>`).join('')+agents.map(a=>`<div class="seat-row"><i class="seat-dot"></i><span>Agent 玩家</span><small>${a.role==='dm'?'DM':esc(state.party.find(p=>p.id===a.characterId)?.name??'玩家')}</small></div>`).join('');}
function renderSeats(){$('seats').innerHTML=seatsMarkup();$('room-seats').innerHTML=seatsMarkup();const taken=new Set([...seats,...agents].map(s=>s.characterId).filter(Boolean));$('agent-character').innerHTML=state.party.map(p=>`<option value="${esc(p.id)}" ${taken.has(p.id)?'disabled':''}>${esc(p.name)}${taken.has(p.id)?' · 已认领':''}</option>`).join('');const first=state.party.find(p=>!taken.has(p.id));if(first)$('agent-character').value=first.id;$('agent-player').disabled=!canManage()||!first;}
function renderCharacters(){$('character-cards').innerHTML=campaign.companions.map((c,i)=>{const p=state.party.find(p=>p.id===c.id);return `<article class="character-card"><div class="portrait">${portraitMarkup(i)}</div><h2>${esc(c.name)}</h2><div class="role">${esc(c.role)}</div><p>${esc(c.description)}</p><div class="stats"><span>生命<b>${p?.maxHp??c.hp}</b></span><span>攻击<b>${c.attack}</b></span><span>护甲<b>${c.armor??0}</b></span><span>射程<b>${c.range??1}</b></span></div><div class="relationship">信任 ${state.relationships[c.id]>=0?'+':''}${state.relationships[c.id]??0} · ${esc(skillNames[c.id]??'')}</div></article>`;}).join('');$('factions').innerHTML=(campaign.factions??[]).map(f=>`<div class="faction"><strong>${esc(f.name)}</strong><p>${esc(f.description)}</p><b>${state.factions[f.id]>=0?'+':''}${state.factions[f.id]??0}</b></div>`).join('');renderMajorNpcs();}
function npcParagraphs(text){return(Array.isArray(text)?text:[text]).filter(Boolean).map(p=>`<p>${esc(p)}</p>`).join('');}
function renderMajorNpcs(){const visible=(campaign.majorNpcs??[]).filter(npc=>!npc.knownFromFlag||state.flags.includes(npc.knownFromFlag));$('major-npcs-section').hidden=!visible.length;$('major-npcs').innerHTML=visible.map(source=>{const npc=rules.majorNpcForState?rules.majorNpcForState(state,source):{...source,relationship:state.npcRelationships?.[source.id]??0,activeStances:(source.stances??[]).filter(s=>meetsRequirements(state,s.requires)),activeMilestones:(source.milestones??[]).filter(s=>meetsRequirements(state,s.requires))},relationship=Number.isFinite(npc.relationship)?npc.relationship:0,portrait=typeof npc.portrait==='string'&&/^\/assets\/[a-zA-Z0-9_/-]+\.(png|webp|jpe?g|svg)$/.test(npc.portrait)?npc.portrait:null;return `<article class="major-npc" aria-labelledby="npc-profile-${esc(npc.id)}"><div class="major-npc-image">${portrait?`<img src="${esc(portrait)}" alt="${esc(npc.name)}的原创人物画像" loading="lazy">`:`<div class="npc-portrait-fallback npc-art" style="background-position-x:${({quetzalcoatl:0,tezcatlipoca:50,mictlan:100})[npc.id]??0}%" aria-hidden="true"></div>`}<span>关键人物 · 不可认领</span></div><div class="major-npc-content"><div class="npc-overline"><span>${esc(npc.title)}</span><span class="npc-relationship">往来 <b>${relationship>=0?'+':''}${esc(relationship)}</b></span></div><h2 id="npc-profile-${esc(npc.id)}">${esc(npc.name)}</h2><div class="npc-description">${npcParagraphs(npc.description)}</div><div class="npc-state-heading">你们之间</div><div class="npc-stances">${npc.activeStances.length?npc.activeStances.map(stance=>`<section class="npc-stance" data-npc-stance="${esc(stance.id)}"><h3>${esc(stance.title??stance.label)}</h3>${npcParagraphs(stance.text)}</section>`).join(''):'<p class="npc-unrecorded">接触中的许可与分歧会记录在这里。</p>'}</div><div class="npc-state-heading">已发生的接触</div><div class="npc-milestones">${npc.activeMilestones.length?npc.activeMilestones.map(milestone=>`<section class="npc-milestone" data-npc-milestone="${esc(milestone.id)}"><h3>${esc(milestone.title??milestone.label)}</h3>${npcParagraphs(milestone.text)}</section>`).join(''):'<p class="npc-unrecorded">新的接触会写入这份档案。</p>'}</div></div></article>`;}).join('');}
function setMode(next){mode=next;renderControls();renderMap();const tips={move:'点击蓝色可达地格移动',attack:'点击射程内的红色敌棋攻击',heal:'点击相邻同伴救治，也可选择自己',skill:selected==='xoco'?'点击 3 格内的同伴使用净水救护':'点击敌棋使用角色特技'};$('tile-info').textContent=tips[next]??'';}
function selectUnit(id){if(!state.party.some(p=>p.id===id))return;selected=id;renderParty();renderMap();renderControls();}
async function unitClick(id,enemy){const u=currentUnit();if((enemy||mode==='heal'||mode==='skill')&&!canAct(u)){toast(state.phase==='combat'?'请等待你控制的角色回合':'请先选择你控制的同行者',true);return;}if(enemy){if(mode==='skill')await action({type:'skill',characterId:u.id,targetId:id});else if(mode==='attack')await action({type:'attack',characterId:u.id,targetId:id});else toast('先选择「攻击」或敌方目标特技');}else if(mode==='heal')await action({type:'heal',characterId:u.id,targetId:id});else if(mode==='skill'&&u.id==='xoco')await action({type:'skill',characterId:u.id,targetId:id});else selectUnit(id);}
function changeView(next){view=next;document.querySelectorAll('.view').forEach(el=>el.classList.toggle('active',el.id===next+'-view'));document.querySelectorAll('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===next));if(next==='editor'){if(!draft)initDraft(currentMap());renderEditor();}if(next==='characters')renderCharacters();}
function initDraft(source){source=copy(source);delete source.variants;delete source.activeVariants;draft={...source,id:'custom-'+Date.now().toString(36),name:source.name+' · 新绘',description:source.description};draftHistory=[];painted=0;$('editor-name').value=draft.name;$('editor-description').value=draft.description;}
function editorSources(){return[...maps,...Object.values(state.customMaps??{})];}
function renderEditor(sourceId=null){const source=sourceId??$('editor-source').value;$('editor-source').innerHTML=editorSources().map(m=>`<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('');if(editorSources().some(m=>m.id===source))$('editor-source').value=source;else $('editor-source').value=state.mapId;$('brushes').innerHTML=Object.entries(terrain).map(([key,t])=>`<button class="brush ${key===brush?'active':''}" data-brush="${key}" title="${t.name}" aria-pressed="${key===brush}"><i class="swatch-${t.class}">${t.icon}</i>${t.name}</button>`).join('');$('editor-board').innerHTML=mapSVG(draft,{editing:true});$('brush-label').textContent=terrain[brush].name;$('spawn-label').textContent=String.fromCharCode(65+draft.spawn.x)+(draft.spawn.y+1);$('editor-status').textContent=painted?'已修改 '+painted+' 格':'尚未修改';$('editor-undo').disabled=draftHistory.length===0;renderSavedMaps();renderControls();}
function renderSavedMaps(){$('custom-maps').innerHTML=Object.values(state.customMaps??{}).map(m=>`<div class="saved-map"><span>${esc(m.name)}</span><button data-edit-map="${esc(m.id)}">${canManage()?'编辑':'查看'}</button><button data-load-map="${esc(m.id)}" ${!may('loadMap')||state.phase!=='exploration'?'disabled':''}>入局</button></div>`).join('')||'<p class="muted">还没有房间地图。绘制后保存，即可载入游戏桌。</p>';}
function paintTile(x,y){if(!draft||!canManage())return;const before=copy(draft);if(brush==='spawn'){if(['#','~'].includes(draft.tiles[y][x])){toast('出生点需放在可通行地格',true);return;}draft.spawn={x,y};}else{if(draft.tiles[y][x]===brush)return;const row=[...draft.tiles[y]];row[x]=brush;draft.tiles[y]=row.join('');if(['#','~'].includes(brush))draft.pois=draft.pois.filter(p=>p.x!==x||p.y!==y);}draftHistory.push(before);if(draftHistory.length>100)draftHistory.shift();painted++;renderEditor();}
function readDraft(){draft.name=$('editor-name').value.trim();draft.description=$('editor-description').value.trim();if(!draft.name)throw Error('请为地图命名');if(['#','~'].includes(draft.tiles[draft.spawn.y][draft.spawn.x]))throw Error('出生点被墙或河水覆盖，请重新指定出生点');return draft;}
async function saveDraft(){if(!canManage()){toast('地图管理需要管理员或主持人席位',true);return false;}try{readDraft();if(draft.id===state.mapId){toast('请先旅行到其他地图，再保存当前地图的编辑。',true);return false;}const ok=await action({type:'saveMap',map:copy(draft)});if(ok){toast('地图已保存至房间');renderEditor(draft.id);}return ok;}catch(e){toast(e.message,true);return false;}}
function download(value,name){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function invitation(){const url=new URL(location.href);url.search='';url.hash='';url.searchParams.set('room',session.roomId);url.searchParams.set('join','1');return url.href;}
async function copyInvitation(){if(!session)return;try{await navigator.clipboard.writeText(invitation());toast('邀请链接已复制');}catch{$('invite-url').value=invitation();$('room-dialog').showModal();$('invite-url').select();toast('请复制选中的邀请链接');}}
async function openRoom(){if(!session){$('welcome-dialog').showModal();return;}$('room-id').value=session.roomId;$('invite-url').value=invitation();$('room-dialog').showModal();await refreshSeats();}
async function openSaves(){if(!session)return;await refreshSaves();$('save-dialog').showModal();}
async function refreshSaves(){try{const data=await request(roomUrl('saves'));$('save-list').innerHTML=data.saves.map(s=>`<div class="save-row"><div><strong>${esc(s.slot)}</strong><small>修订 ${s.revision} · ${esc(new Date(s.savedAt).toLocaleString('zh-CN'))}</small></div><button data-restore="${esc(s.slot)}" ${canManage()?'':'disabled'}>恢复</button></div>`).join('')||'<p class="muted">尚无命名存档</p>';}catch(e){toast(e.message,true);}}
async function acceptSession(data){session={...data};delete session.state;selected=data.characterId??data.state.viewer?.characterId??data.state.selectedCharacter;setState(data.state);session.role=state.viewer?.role??session.role;session.characterId=state.viewer?.characterId??session.characterId;session.roomMode=state.roomMode??state.viewer?.roomMode??data.roomMode??'hosted';session.canManage=canManage();storeSession();connectEvents();await refreshSeats();$('welcome-dialog').close();history.replaceState(null,'',location.pathname+'?room='+encodeURIComponent(session.roomId));}
async function restoreSession(saved){session=saved;const next=await request(roomUrl('state'));session.role=next.viewer.role;session.characterId=next.viewer.characterId;session.roomMode=next.roomMode??next.viewer.roomMode??'hosted';selected=session.characterId??next.selectedCharacter;setState(next);session.canManage=canManage();storeSession();connectEvents();await refreshSeats();$('welcome-dialog').close();history.replaceState(null,'',location.pathname+'?room='+encodeURIComponent(session.roomId));}
async function agentSeat(role){if(!canManage()){toast('创建智能体需要管理员或主持人席位',true);return;}try{const result=await request(roomUrl('agents'),{method:'POST',body:{role,...(role==='player'?{characterId:$('agent-character').value}:{})}});$('agent-result').hidden=false;$('agent-result').textContent='已创建 '+(role==='dm'?'可选 DM':'Agent 玩家')+'\n'+result.folder+'\n\n让 agent 阅读 docs/AGENT_PROTOCOL.md，按 snapshot.json 的最新局面提交行动。';await refreshSeats();}catch(e){toast(e.message,true);}}

function bind(){
 document.querySelectorAll('[data-view]').forEach(b=>{const symbol=b.querySelector('span');if(symbol)symbol.innerHTML=icon(b.dataset.view);});
 const unitStatus=document.createElement('span');unitStatus.id='unit-status';unitStatus.className='unit-status';$('grid-toggle').before(unitStatus);
 const chapter=document.createElement('section');chapter.id='chapter-summary';chapter.className='chapter-summary';$('routes').before(chapter);chapter.addEventListener('click',e=>{if(e.target.closest('#chapter-recap'))$('journey-dialog').showModal();});const journey=document.createElement('dialog');journey.id='journey-dialog';journey.className='journey-dialog';journey.innerHTML='<div class="dialog-heading"><div><div class="eyebrow">旅 程 回 顾</div><h2>旅程回顾</h2></div><button id="journey-close" aria-label="关闭旅程回顾">×</button></div><div id="journey-body"></div>';document.body.append(journey);$('journey-close').addEventListener('click',()=>journey.close());const journeyOpen=document.createElement('button');journeyOpen.id='journey-open';journeyOpen.innerHTML='<span>'+icon('journey')+'</span>旅程回顾';document.querySelector('.rail-art').before(journeyOpen);journeyOpen.addEventListener('click',()=>journey.showModal());
 const worldChanges=document.createElement('div');worldChanges.id='world-changes';worldChanges.className='world-changes';worldChanges.hidden=true;$('game-board').closest('.board-frame').before(worldChanges);const encounter=document.createElement('div');encounter.id='encounter-controls';encounter.className='encounter-controls';encounter.hidden=true;encounter.innerHTML='<span>自制图遭遇</span><select id="encounter-template" aria-label="工坊遭遇模板"><option value="reeds">芦苇巡守 · 演练</option><option value="shades">骨渡守卫</option></select><button id="encounter-start" title="仅管理员或主持可开始自制图遭遇">⚔ 开始遭遇</button>';$('game-board').closest('.board-frame').after(encounter);
 document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>changeView(b.dataset.view)));document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();changeView('table');});document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>$(b.dataset.close).close()));
 document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.mode)));$('party').addEventListener('click',e=>{const b=e.target.closest('[data-character]');if(b)selectUnit(b.dataset.character);});
 $('game-board').addEventListener('click',async e=>{const token=e.target.closest('[data-unit]');if(token)return unitClick(token.dataset.unit,token.dataset.enemy==='true');const tile=e.target.closest('[data-x]');if(tile&&mode==='move'){if(!canAct(currentUnit()))return toast(state.phase==='combat'?'请等待你控制的角色回合':'请先选择你控制的同行者',true);await action({type:'move',characterId:currentUnit().id,x:+tile.dataset.x,y:+tile.dataset.y});}});$('game-board').addEventListener('keydown',e=>{const token=e.target.closest('[data-unit]');if(token&&['Enter',' '].includes(e.key)){e.preventDefault();unitClick(token.dataset.unit,token.dataset.enemy==='true');}});
 $('game-board').addEventListener('pointermove',e=>{const tile=e.target.closest('[data-x]');if(!tile)return;const x=+tile.dataset.x,y=+tile.dataset.y;$('tile-info').textContent=String.fromCharCode(65+x)+(y+1)+' · '+terrainNameFor(currentMap(),x,y)+' · '+(mode==='move'?'点击移动':mode==='attack'?'选择敌方棋子':mode==='skill'?'选择特技目标':'选择同伴救治');});
 $('grid-toggle').addEventListener('click',()=>{grid=!grid;$('grid-toggle').textContent='网格：'+(grid?'开':'关');$('grid-toggle').setAttribute('aria-pressed',String(grid));$('game-board').classList.toggle('no-grid',!grid);});
 $('guard').addEventListener('click',()=>action({type:'guard',characterId:selected}));$('end-turn').addEventListener('click',()=>action({type:'endTurn',characterId:selected}));$('rest').addEventListener('click',()=>action({type:'rest'}));$('retreat').addEventListener('click',()=>action({type:'retreat'}));$('travel-go').addEventListener('click',async()=>{await action({type:'travel',mapId:$('travel-map').value});});
 $('encounter-start').addEventListener('click',()=>action({type:'startEncounter',templateId:$('encounter-template').value}));
 $('routes').addEventListener('click',e=>{const b=e.target.closest('[data-route]');if(b){activeRoute=b.dataset.route;activeNode=null;renderStory();}});$('story').addEventListener('click',async e=>{const choice=e.target.closest('[data-choice]'),travel=e.target.closest('[data-travel]'),node=e.target.closest('[data-node]');if(choice)await action({type:'choose',nodeId:choice.dataset.choiceNode,choiceId:choice.dataset.choice});if(travel){activeRoute=travel.dataset.travelRoute;await action({type:'travel',mapId:travel.dataset.travel});}if(node){activeNode=node.dataset.node;renderStory();}if(e.target.closest('#finale'))await action({type:'finale'});if(e.target.closest('#story-rest'))await action({type:'rest'});const npcProfile=e.target.closest('[data-npc-profile]');if(npcProfile){changeView('characters');document.getElementById('npc-profile-'+npcProfile.dataset.npcProfile)?.closest('.major-npc')?.scrollIntoView({block:'start'});}});
 $('room-open').addEventListener('click',openRoom);$('save-open').addEventListener('click',openSaves);$('invite-copy').addEventListener('click',copyInvitation);$('room-copy').addEventListener('click',copyInvitation);$('seats-refresh').addEventListener('click',refreshSeats);$('agent-dm').addEventListener('click',()=>agentSeat('dm'));$('agent-player').addEventListener('click',()=>agentSeat('player'));
 $('save-now').addEventListener('click',async()=>{const slot=$('save-slot').value.trim();if(!/^[a-zA-Z0-9_-]{1,64}$/.test(slot))return toast('存档名须为 1—64 位字母、数字、下划线或短横线',true);try{await request(roomUrl('save'),{method:'POST',body:{slot}});toast('已封存当前进度');await refreshSaves();}catch(e){toast(e.message,true);}});$('save-list').addEventListener('click',async e=>{const b=e.target.closest('[data-restore]');if(!b)return;try{const data=await request(roomUrl('load'),{method:'POST',body:{slot:b.dataset.restore}});setState(data.state);toast('已恢复存档：'+b.dataset.restore);$('save-dialog').close();}catch(e){toast(e.message,true);}});$('export-game').addEventListener('click',async()=>{try{download(await request(roomUrl('export'),{method:'POST',body:{}}),'aztec-'+session.roomId+'.json');toast('游戏 JSON 已导出');}catch(e){toast(e.message,true);}});
 $('editor-source').addEventListener('change',()=>{const source=mapById($('editor-source').value);initDraft(source);renderEditor();});$('brushes').addEventListener('click',e=>{const b=e.target.closest('[data-brush]');if(b){brush=b.dataset.brush;renderEditor();}});$('editor-board').addEventListener('pointerdown',e=>{const t=e.target.closest('[data-x]');if(t){e.preventDefault();painting=true;paintTile(+t.dataset.x,+t.dataset.y);}});$('editor-board').addEventListener('pointerover',e=>{if(!painting||!(e.buttons&1))return;const t=e.target.closest('[data-x]');if(t)paintTile(+t.dataset.x,+t.dataset.y);});document.addEventListener('pointerup',()=>painting=false);
 $('editor-name').addEventListener('input',()=>{if(draft)draft.name=$('editor-name').value;});$('editor-description').addEventListener('input',()=>{if(draft)draft.description=$('editor-description').value;});$('editor-undo').addEventListener('click',()=>{if(!draftHistory.length)return;draft=draftHistory.pop();painted=Math.max(0,painted-1);renderEditor();});$('editor-reset').addEventListener('click',()=>{initDraft(mapById($('editor-source').value));renderEditor();});$('editor-save').addEventListener('click',saveDraft);
 $('editor-reload').addEventListener('click',async()=>{try{await sync();const source=state.customMaps[draft.id]??mapById($('editor-source').value);if(state.customMaps[draft.id]){draft=copy(source);draftHistory=[];painted=0;$('editor-name').value=draft.name;$('editor-description').value=draft.description;}else initDraft(source);renderEditor();toast('已重载服务端地图');}catch(e){toast(e.message,true);}});$('editor-play').addEventListener('click',async()=>{if(await saveDraft()){if(await action({type:'loadMap',mapId:draft.id})){changeView('table');toast('已载入自绘地图');}}});$('editor-export').addEventListener('click',()=>{if(!canManage())return toast('导出地图需要管理员或主持人席位',true);try{download(readDraft(),draft.id+'.json');toast('地图 JSON 已导出');}catch(e){toast(e.message,true);}});$('custom-maps').addEventListener('click',async e=>{const edit=e.target.closest('[data-edit-map]'),load=e.target.closest('[data-load-map]');if(edit){draft=copy(state.customMaps[edit.dataset.editMap]);draftHistory=[];painted=0;$('editor-name').value=draft.name;$('editor-description').value=draft.description;renderEditor(edit.dataset.editMap);}if(load&&await action({type:'loadMap',mapId:load.dataset.loadMap}))changeView('table');});
 $('welcome-form').addEventListener('submit',async e=>{e.preventDefault();const name=$('player-name').value.trim();if(!name)return;$('welcome-submit').disabled=true;$('welcome-error').textContent='';try{const joining=$('welcome-form').dataset.join;const roomMode=$('room-mode').value,body=joining?{name,characterId:$('join-character').value}:{name,mode:roomMode,...(roomMode==='party'?{characterId:$('join-character').value}:{})};const result=await request(joining?'/api/rooms/'+encodeURIComponent(joining)+'/join':'/api/rooms',{method:'POST',auth:false,body});await acceptSession(result);}catch(error){$('welcome-error').textContent=error.message;}finally{$('welcome-submit').disabled=false;}});
 $('room-mode').addEventListener('change',updateWelcomeMode);$('welcome-dialog').addEventListener('cancel',e=>{if(!session)e.preventDefault();});$('new-room').addEventListener('click',()=>{delete $('welcome-form').dataset.join;$('room-mode').value=edition.defaultRoomMode;updateWelcomeMode();$('welcome-error').textContent='';$('welcome-dialog').showModal();});
 document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||document.querySelector('dialog[open]'))return;const key=e.key.toLowerCase();if(['m','a','h'].includes(key)&&view==='table'){e.preventDefault();const m={m:'move',a:'attack',h:'heal'}[key];if(!document.querySelector('[data-mode="'+m+'"]').disabled)setMode(m);}if(key==='g'&&!$('guard').disabled)$('guard').click();});
}
async function boot(){
 try{const data=await request('/api/content',{auth:false});campaign=data.campaign;edition={...edition,...data.edition};maps=data.maps;if(!campaign||!maps.length)throw Error('游戏内容未载入');storageKey='aztec-fifth-sun-v3-seat:'+edition.version+':'+campaign.id;state=createState(campaign,maps);selected=state.selectedCharacter;bind();$('room-mode').value=edition.defaultRoomMode;updateWelcomeMode();render();$('join-character').innerHTML=campaign.companions.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} · ${esc(c.role)}</option>`).join('');const welcomeText=typeof campaign.welcomeText==='string'&&campaign.welcomeText.trim()?campaign.welcomeText.trim():Array.isArray(campaign.intro)?campaign.intro[0]:String(campaign.intro??'').split(/\r?\n\s*\r?\n|\r?\n/)[0];$('welcome-intro').textContent=welcomeText||$('welcome-intro').textContent;
  document.title=edition.title??campaign.title;let saved;if(!queryJoin){try{saved=JSON.parse(sessionStorage.getItem(storageKey));if(!saved){const key=localStorage.getItem(storageKey+':last-manager');if(key)saved=JSON.parse(localStorage.getItem(key));}}catch{}}if(saved?.token&&(!queryRoom||queryRoom===saved.roomId)){try{await restoreSession(saved);return;}catch(error){status(false,'席位待恢复');$('resume-button').hidden=false;$('resume-button').onclick=async()=>{try{await restoreSession(saved);}catch(e){$('welcome-error').textContent=e.message;}};$('welcome-error').textContent='本机席位暂未恢复，可重试或开启新的旅程。';session=null;}}
  if(queryRoom){$('welcome-form').dataset.join=queryRoom;updateWelcomeMode();$('welcome-intro').textContent='有人在船上为你留了一个位置。输入名字，选择一位尚未被认领的同行者。邀请用于同机浏览器席位，跨设备连接尚未验证。';}status(false,'等待入席');$('welcome-dialog').showModal();
 }catch(error){status(false,'内容载入失败');toast(error.message,true);$('main').innerHTML='<div class="tablet"><h1>暂时无法进入第五日之城</h1><p>'+esc(error.message)+'</p><button id="reload-content">重新载入</button></div>';$('reload-content').addEventListener('click',()=>location.reload());}
}
boot();
